
const BANK = [{"id":1,"subject":"History","en":"Who founded the Satyashodhak Samaj in 1873?","mr":"१८७३ मध्ये सत्यशोधक समाजाची स्थापना कोणी केली?","options":["Jyotirao Phule","Mahatma Gandhi","Gopal Krishna Gokhale","B. R. Ambedkar"],"answer":0,"explanationEn":"Mahatma Jyotirao Phule founded the Satyashodhak Samaj in 1873.","explanationMr":"महात्मा ज्योतिराव फुले यांनी १८७३ मध्ये सत्यशोधक समाजाची स्थापना केली."},{"id":2,"subject":"History","en":"Who was the first woman teacher of modern India?","mr":"आधुनिक भारतातील पहिल्या महिला शिक्षिका कोण होत्या?","options":["Savitribai Phule","Pandita Ramabai","Anandibai Joshi","Ramabai Ranade"],"answer":0,"explanationEn":"Savitribai Phule is widely recognised as India's first woman teacher.","explanationMr":"सावित्रीबाई फुले यांना भारतातील पहिल्या महिला शिक्षिका म्हणून ओळखले जाते."},{"id":3,"subject":"History","en":"In which year was the Indian National Congress founded?","mr":"भारतीय राष्ट्रीय काँग्रेसची स्थापना कोणत्या वर्षी झाली?","options":["1885","1887","1905","1919"],"answer":0,"explanationEn":"The Indian National Congress was founded in 1885.","explanationMr":"भारतीय राष्ट्रीय काँग्रेसची स्थापना १८८५ मध्ये झाली."},{"id":4,"subject":"History","en":"Who founded the Servants of India Society?","mr":"भारत सेवक समाजाची स्थापना कोणी केली?","options":["Gopal Krishna Gokhale","Bal Gangadhar Tilak","M. G. Ranade","Dadabhai Naoroji"],"answer":0,"explanationEn":"Gopal Krishna Gokhale founded the Servants of India Society in 1905.","explanationMr":"गोपाल कृष्ण गोखले यांनी १९०५ मध्ये भारत सेवक समाजाची स्थापना केली."},{"id":5,"subject":"History","en":"The Poona Pact was signed in which year?","mr":"पुणे करार कोणत्या वर्षी झाला?","options":["1928","1930","1932","1935"],"answer":2,"explanationEn":"The Poona Pact between Gandhi and Ambedkar was signed in 1932.","explanationMr":"गांधी आणि आंबेडकर यांच्यातील पुणे करार १९३२ मध्ये झाला."},{"id":6,"subject":"History","en":"Who founded the Bahishkrit Hitakarini Sabha?","mr":"बहिष्कृत हितकारिणी सभेची स्थापना कोणी केली?","options":["Dr. B. R. Ambedkar","Shahu Maharaj","Jyotirao Phule","V. R. Shinde"],"answer":0,"explanationEn":"Dr. B. R. Ambedkar founded it in 1924.","explanationMr":"डॉ. बाबासाहेब आंबेडकर यांनी १९२४ मध्ये ही संस्था स्थापन केली."},{"id":7,"subject":"History","en":"Who was popularly known as Lokhitwadi?","mr":"लोकहितवादी म्हणून कोण ओळखले जातात?","options":["Gopal Hari Deshmukh","Vishnushastri Chiplunkar","M. G. Ranade","Gopal Ganesh Agarkar"],"answer":0,"explanationEn":"Gopal Hari Deshmukh wrote under the pen name Lokhitwadi.","explanationMr":"गोपाळ हरी देशमुख यांनी लोकहितवादी या नावाने लेखन केले."},{"id":8,"subject":"History","en":"The Quit India Movement began in which year?","mr":"भारत छोडो आंदोलन कोणत्या वर्षी सुरू झाले?","options":["1930","1935","1942","1946"],"answer":2,"explanationEn":"The Quit India Movement was launched in August 1942.","explanationMr":"भारत छोडो आंदोलन ऑगस्ट १९४२ मध्ये सुरू झाले."},{"id":9,"subject":"History","en":"Who founded the Deccan Education Society with his associates?","mr":"सहकाऱ्यांसह डेक्कन एज्युकेशन सोसायटीच्या स्थापनेत प्रमुख भूमिका कोणी बजावली?","options":["Bal Gangadhar Tilak","Mahatma Gandhi","Dadabhai Naoroji","Sardar Patel"],"answer":0,"explanationEn":"Tilak, Agarkar and other associates were among its founders in 1884.","explanationMr":"१८८४ मध्ये टिळक, आगरकर आणि त्यांच्या सहकाऱ्यांनी या संस्थेच्या स्थापनेत सहभाग घेतला."},{"id":10,"subject":"History","en":"Who was the first Indian woman president of the Indian National Congress?","mr":"भारतीय राष्ट्रीय काँग्रेसच्या पहिल्या भारतीय महिला अध्यक्षा कोण होत्या?","options":["Sarojini Naidu","Annie Besant","Vijayalakshmi Pandit","Sucheta Kripalani"],"answer":0,"explanationEn":"Sarojini Naidu presided over the 1925 Kanpur session.","explanationMr":"सरोजिनी नायडू यांनी १९२५ च्या कानपूर अधिवेशनाचे अध्यक्षस्थान भूषवले."},{"id":11,"subject":"Geography","en":"Which is the longest river flowing through Maharashtra?","mr":"महाराष्ट्रातून वाहणारी सर्वात लांब नदी कोणती?","options":["Godavari","Krishna","Tapi","Wardha"],"answer":0,"explanationEn":"The Godavari is the longest river flowing through Maharashtra.","explanationMr":"गोदावरी ही महाराष्ट्रातून वाहणारी सर्वात लांब नदी आहे."},{"id":12,"subject":"Geography","en":"Which is the highest peak in Maharashtra?","mr":"महाराष्ट्रातील सर्वात उंच शिखर कोणते?","options":["Kalsubai","Salher","Harishchandragad","Taramati"],"answer":0,"explanationEn":"Kalsubai, in the Sahyadri range, is Maharashtra's highest peak.","explanationMr":"सह्याद्री पर्वतरांगेतील कळसूबाई हे महाराष्ट्रातील सर्वोच्च शिखर आहे."},{"id":13,"subject":"Geography","en":"Kalsubai peak is located in which district?","mr":"कळसूबाई शिखर कोणत्या जिल्ह्यात आहे?","options":["Ahilyanagar","Nashik","Pune","Satara"],"answer":0,"explanationEn":"Kalsubai is in Akole taluka of Ahilyanagar district.","explanationMr":"कळसूबाई अहिल्यानगर जिल्ह्यातील अकोले तालुक्यात आहे."},{"id":14,"subject":"Geography","en":"Which soil is especially suitable for cotton cultivation?","mr":"कापूस लागवडीसाठी कोणती माती विशेष उपयुक्त आहे?","options":["Black soil","Laterite soil","Desert soil","Mountain soil"],"answer":0,"explanationEn":"Black cotton soil retains moisture and is suitable for cotton.","explanationMr":"काळी माती ओलावा टिकवून ठेवते आणि कापसासाठी उपयुक्त असते."},{"id":15,"subject":"Geography","en":"The Tapi river drains into which water body?","mr":"तापी नदी कोणत्या जलाशयात मिळते?","options":["Arabian Sea","Bay of Bengal","Indian Ocean near Chennai","Gulf of Mannar"],"answer":0,"explanationEn":"The Tapi flows westward and enters the Arabian Sea.","explanationMr":"तापी नदी पश्चिमेकडे वाहून अरबी समुद्राला मिळते."},{"id":16,"subject":"Geography","en":"Which city is situated on the banks of the Godavari?","mr":"गोदावरी नदीच्या काठावर कोणते शहर वसले आहे?","options":["Nashik","Kolhapur","Satara","Sangli"],"answer":0,"explanationEn":"The Godavari flows through Nashik.","explanationMr":"गोदावरी नदी नाशिक शहरातून वाहते."},{"id":17,"subject":"Geography","en":"Which ghat route connects Mumbai and Pune?","mr":"मुंबई आणि पुणे यांना जोडणारा प्रमुख घाटमार्ग कोणता?","options":["Bhor Ghat","Thal Ghat","Naneghat","Malshej Ghat"],"answer":0,"explanationEn":"Bhor Ghat is the traditional route between Mumbai and Pune.","explanationMr":"भोर घाट हा मुंबई-पुणे दरम्यानचा पारंपरिक घाटमार्ग आहे."},{"id":18,"subject":"Geography","en":"Which region of Maharashtra receives heavy orographic rainfall?","mr":"महाराष्ट्रातील कोणत्या भागात पर्वतीय अडथळ्यामुळे भरपूर पाऊस पडतो?","options":["Konkan and windward Western Ghats","Marathwada plateau","Vidarbha plains","Rain-shadow interior"],"answer":0,"explanationEn":"Moisture-laden southwest monsoon winds rise along the Western Ghats.","explanationMr":"नैऋत्य मोसमी वारे सह्याद्रीला धडकून वर चढतात आणि कोकणात भरपूर पाऊस पडतो."},{"id":19,"subject":"Geography","en":"Nagpur is especially known for which fruit?","mr":"नागपूर कोणत्या फळासाठी विशेष प्रसिद्ध आहे?","options":["Orange","Mango","Grapes","Pomegranate"],"answer":0,"explanationEn":"Nagpur is widely associated with oranges.","explanationMr":"नागपूर संत्र्यांसाठी प्रसिद्ध आहे."},{"id":20,"subject":"Geography","en":"Which river is popularly called Dakshin Ganga?","mr":"दक्षिण गंगा म्हणून कोणती नदी ओळखली जाते?","options":["Godavari","Krishna","Kaveri","Narmada"],"answer":0,"explanationEn":"The Godavari is popularly known as Dakshin Ganga.","explanationMr":"गोदावरी नदीला दक्षिण गंगा असेही म्हणतात."},{"id":21,"subject":"Polity","en":"When did the Constitution of India come into force?","mr":"भारतीय संविधान कधी अमलात आले?","options":["26 January 1950","26 November 1949","15 August 1947","2 October 1950"],"answer":0,"explanationEn":"The Constitution came into force on 26 January 1950.","explanationMr":"भारतीय संविधान २६ जानेवारी १९५० रोजी अमलात आले."},{"id":22,"subject":"Polity","en":"Which Article guarantees equality before the law?","mr":"कायद्यासमोर समानतेचा अधिकार कोणत्या कलमात आहे?","options":["Article 14","Article 19","Article 21","Article 32"],"answer":0,"explanationEn":"Article 14 provides equality before law and equal protection of laws.","explanationMr":"कलम १४ कायद्यासमोर समानता आणि कायद्यांचे समान संरक्षण देते."},{"id":23,"subject":"Polity","en":"Who appoints the Governor of an Indian state?","mr":"भारतीय राज्याच्या राज्यपालांची नियुक्ती कोण करतात?","options":["President","Prime Minister","Chief Minister","Chief Justice of India"],"answer":0,"explanationEn":"The President appoints state Governors under Article 155.","explanationMr":"कलम १५५ नुसार राष्ट्रपती राज्यपालांची नियुक्ती करतात."},{"id":24,"subject":"Polity","en":"Which amendment gave constitutional status to Panchayati Raj institutions?","mr":"पंचायतराज संस्थांना घटनात्मक दर्जा कोणत्या घटनादुरुस्तीने दिला?","options":["73rd","42nd","44th","74th"],"answer":0,"explanationEn":"The 73rd Constitutional Amendment Act, 1992 concerns Panchayats.","explanationMr":"१९९२ च्या ७३ व्या घटनादुरुस्तीने पंचायतींना घटनात्मक दर्जा दिला."},{"id":25,"subject":"Polity","en":"Which Article deals with the Right to Life and Personal Liberty?","mr":"जीवन व व्यक्तिगत स्वातंत्र्याचा अधिकार कोणत्या कलमात आहे?","options":["Article 21","Article 14","Article 19","Article 25"],"answer":0,"explanationEn":"Article 21 protects life and personal liberty.","explanationMr":"कलम २१ जीवन आणि व्यक्तिगत स्वातंत्र्याचे संरक्षण करते."},{"id":26,"subject":"Polity","en":"The Finance Commission is constituted under which Article?","mr":"वित्त आयोगाची तरतूद कोणत्या कलमात आहे?","options":["Article 280","Article 324","Article 356","Article 368"],"answer":0,"explanationEn":"Article 280 provides for a Finance Commission.","explanationMr":"कलम २८० मध्ये वित्त आयोगाची तरतूद आहे."},{"id":27,"subject":"Polity","en":"Which Schedule of the Constitution lists recognised languages?","mr":"संविधानाच्या कोणत्या अनुसूचीत मान्यताप्राप्त भाषांची यादी आहे?","options":["Eighth","Seventh","Fifth","Tenth"],"answer":0,"explanationEn":"The Eighth Schedule lists the constitutionally recognised languages.","explanationMr":"आठव्या अनुसूचीत संविधानमान्य भाषांची यादी आहे."},{"id":28,"subject":"Polity","en":"Who presides over the Lok Sabha?","mr":"लोकसभेचे अध्यक्षस्थान कोण भूषवतात?","options":["Speaker","President","Vice-President","Prime Minister"],"answer":0,"explanationEn":"The Speaker presides over Lok Sabha sittings.","explanationMr":"लोकसभेच्या कामकाजाचे अध्यक्षस्थान सभापती भूषवतात."},{"id":29,"subject":"Polity","en":"Which body conducts elections to Parliament and State Legislatures?","mr":"संसद आणि राज्य विधानमंडळांच्या निवडणुका कोणती संस्था घेते?","options":["Election Commission of India","UPSC","Finance Commission","NITI Aayog"],"answer":0,"explanationEn":"The Election Commission of India conducts these elections under Article 324.","explanationMr":"कलम ३२४ नुसार भारतीय निवडणूक आयोग या निवडणुका घेतो."},{"id":30,"subject":"Polity","en":"Fundamental Duties were added by which amendment?","mr":"मूलभूत कर्तव्ये कोणत्या घटनादुरुस्तीने समाविष्ट करण्यात आली?","options":["42nd","44th","52nd","61st"],"answer":0,"explanationEn":"The 42nd Amendment Act, 1976 added Fundamental Duties.","explanationMr":"१९७६ च्या ४२ व्या घटनादुरुस्तीने मूलभूत कर्तव्ये समाविष्ट केली."},{"id":31,"subject":"Economy","en":"Which institution formulates monetary policy in India?","mr":"भारतातील चलनविषयक धोरण कोण ठरवते?","options":["Reserve Bank of India","SEBI","NABARD","Finance Commission"],"answer":0,"explanationEn":"The RBI's Monetary Policy Committee determines the policy rate framework.","explanationMr":"रिझर्व्ह बँकेची चलनविषयक धोरण समिती धोरणात्मक व्याजदर ठरवते."},{"id":32,"subject":"Economy","en":"GST was implemented in India from which date?","mr":"भारतात GST कोणत्या तारखेपासून लागू झाला?","options":["1 July 2017","1 April 2017","1 January 2018","15 August 2017"],"answer":0,"explanationEn":"GST was introduced on 1 July 2017.","explanationMr":"GST १ जुलै २०१७ पासून लागू झाला."},{"id":33,"subject":"Economy","en":"Which of the following is a direct tax?","mr":"खालीलपैकी कोणता प्रत्यक्ष कर आहे?","options":["Income Tax","GST","Customs Duty","Excise Duty"],"answer":0,"explanationEn":"Income tax is levied directly on the income of a person or entity.","explanationMr":"प्राप्तिकर हा व्यक्ती किंवा संस्थेच्या उत्पन्नावर थेट आकारला जातो."},{"id":34,"subject":"Economy","en":"NABARD is primarily associated with which sector?","mr":"नाबार्ड मुख्यतः कोणत्या क्षेत्राशी संबंधित आहे?","options":["Agriculture and rural development","Capital markets","Defence","Telecommunications"],"answer":0,"explanationEn":"NABARD supports agriculture and rural development finance.","explanationMr":"नाबार्ड कृषी आणि ग्रामीण विकासासाठी वित्तपुरवठा व सहाय्य करते."},{"id":35,"subject":"Economy","en":"What does GDP stand for?","mr":"GDP चे पूर्ण रूप काय आहे?","options":["Gross Domestic Product","General Domestic Production","Gross Development Plan","General Development Product"],"answer":0,"explanationEn":"GDP measures the value of final goods and services produced domestically.","explanationMr":"GDP देशांतर्गत उत्पादित अंतिम वस्तू व सेवांचे मूल्य मोजते."},{"id":36,"subject":"Economy","en":"Which regulator oversees the securities market in India?","mr":"भारतातील प्रतिभूती बाजाराचे नियमन कोण करते?","options":["SEBI","RBI","IRDAI","PFRDA"],"answer":0,"explanationEn":"SEBI regulates India's securities market.","explanationMr":"SEBI भारताच्या प्रतिभूती बाजाराचे नियमन करते."},{"id":37,"subject":"Economy","en":"Fiscal deficit is broadly the excess of total expenditure over which amount?","mr":"राजकोषीय तूट म्हणजे एकूण खर्च कोणत्या रकमेपेक्षा जास्त असणे?","options":["Total receipts excluding borrowings","Tax revenue only","Revenue expenditure only","Exports"],"answer":0,"explanationEn":"Fiscal deficit is total expenditure minus receipts excluding debt creating capital receipts.","explanationMr":"कर्जनिर्मिती करणाऱ्या प्राप्ती वगळून एकूण प्राप्तीपेक्षा खर्च जास्त असणे म्हणजे राजकोषीय तूट."},{"id":38,"subject":"Economy","en":"Which is a Kharif crop?","mr":"खालीलपैकी कोणते खरीप पीक आहे?","options":["Rice","Wheat","Gram","Mustard"],"answer":0,"explanationEn":"Rice is commonly grown as a Kharif crop in India.","explanationMr":"भारतात भात हे सामान्यतः खरीप हंगामातील पीक आहे."},{"id":39,"subject":"Economy","en":"Inflation refers to what?","mr":"महागाई म्हणजे काय?","options":["Sustained rise in the general price level","Fall in general prices","Rise in output only","Fall in money supply only"],"answer":0,"explanationEn":"Inflation is a sustained increase in the general price level.","explanationMr":"सर्वसाधारण किंमत पातळीत सातत्याने होणारी वाढ म्हणजे महागाई."},{"id":40,"subject":"Science","en":"What is the SI unit of force?","mr":"बलाचे SI एकक कोणते?","options":["Newton","Joule","Watt","Pascal"],"answer":0,"explanationEn":"Force is measured in newtons.","explanationMr":"बल न्यूटनमध्ये मोजले जाते."},{"id":41,"subject":"Science","en":"Which vitamin is synthesised in skin with sunlight exposure?","mr":"सूर्यप्रकाशाच्या संपर्कात त्वचेत कोणते जीवनसत्त्व तयार होते?","options":["Vitamin D","Vitamin A","Vitamin C","Vitamin B12"],"answer":0,"explanationEn":"UVB exposure helps the skin synthesise vitamin D.","explanationMr":"UVB किरणांमुळे त्वचेत जीवनसत्त्व D तयार होण्यास मदत होते."},{"id":42,"subject":"Science","en":"What is the chemical formula of common salt?","mr":"सामान्य मिठाचे रासायनिक सूत्र काय आहे?","options":["NaCl","KCl","CaCO3","NaOH"],"answer":0,"explanationEn":"Common salt is sodium chloride, NaCl.","explanationMr":"सामान्य मीठ म्हणजे सोडियम क्लोराइड, NaCl."},{"id":43,"subject":"Science","en":"Which organs filter blood and produce urine?","mr":"रक्त गाळून मूत्र तयार करणारे अवयव कोणते?","options":["Kidneys","Lungs","Heart","Stomach"],"answer":0,"explanationEn":"The kidneys filter blood and form urine.","explanationMr":"मूत्रपिंडे रक्त गाळून मूत्र तयार करतात."},{"id":44,"subject":"Science","en":"What is the pH of pure water at 25°C?","mr":"२५°C तापमानाला शुद्ध पाण्याचा pH किती असतो?","options":["7","5","6","9"],"answer":0,"explanationEn":"Pure water is neutral at pH 7 at 25°C.","explanationMr":"२५°C ला शुद्ध पाणी pH ७ असलेले उदासीन द्रावण असते."},{"id":45,"subject":"Science","en":"Which gas is released during oxygenic photosynthesis?","mr":"प्रकाशसंश्लेषणात कोणता वायू बाहेर पडतो?","options":["Oxygen","Carbon dioxide","Nitrogen","Hydrogen"],"answer":0,"explanationEn":"Oxygen is released when water is split during photosynthesis.","explanationMr":"प्रकाशसंश्लेषणात पाण्याचे विघटन झाल्यावर ऑक्सिजन बाहेर पडतो."},{"id":46,"subject":"Science","en":"Which blood group is the universal red-cell donor?","mr":"लाल रक्तपेशींच्या संक्रमणासाठी सार्वत्रिक दाता कोणता रक्तगट मानला जातो?","options":["O negative","AB positive","A positive","B negative"],"answer":0,"explanationEn":"O-negative red cells are considered the universal donor type in standard transfusion teaching.","explanationMr":"O निगेटिव्ह लाल रक्तपेशी सार्वत्रिक दाता म्हणून मानल्या जातात."},{"id":47,"subject":"Science","en":"Which plant part primarily absorbs water from soil?","mr":"मातीतून पाणी प्रामुख्याने वनस्पतीचा कोणता भाग शोषतो?","options":["Root","Leaf","Flower","Fruit"],"answer":0,"explanationEn":"Roots, especially root hairs, absorb water and minerals.","explanationMr":"मुळे, विशेषतः मूलरोम, पाणी व खनिजे शोषतात."},{"id":48,"subject":"Science","en":"What is the approximate speed of light in vacuum?","mr":"निर्वातातील प्रकाशाचा अंदाजे वेग किती?","options":["3 × 10^8 m/s","3 × 10^6 m/s","3 × 10^5 m/s","3 × 10^7 m/s"],"answer":0,"explanationEn":"The speed of light in vacuum is approximately 299,792,458 m/s.","explanationMr":"निर्वातातील प्रकाशाचा वेग अंदाजे २९९,७९२,४५८ मी/से आहे."},{"id":49,"subject":"Science","en":"Which cell structure contains most of the cell's genetic material?","mr":"पेशीतील बहुतांश आनुवंशिक पदार्थ कोणत्या रचनेत असतो?","options":["Nucleus","Ribosome","Cell membrane","Golgi body"],"answer":0,"explanationEn":"In eukaryotic cells, most DNA is housed in the nucleus.","explanationMr":"यूकॅरियोटिक पेशींमध्ये बहुतांश DNA केंद्रकात असतो."},{"id":50,"subject":"Science","en":"Which metal is liquid at ordinary room temperature?","mr":"सामान्य खोलीच्या तापमानाला कोणता धातू द्रवरूपात असतो?","options":["Mercury","Iron","Copper","Aluminium"],"answer":0,"explanationEn":"Mercury is liquid at ordinary room temperature.","explanationMr":"पारा सामान्य खोलीच्या तापमानाला द्रवरूपात असतो."},{"id":51,"subject":"Science","en":"Deficiency of vitamin C causes which disease?","mr":"जीवनसत्त्व C च्या कमतरतेमुळे कोणता रोग होतो?","options":["Scurvy","Rickets","Beriberi","Night blindness"],"answer":0,"explanationEn":"Vitamin C deficiency causes scurvy.","explanationMr":"जीवनसत्त्व C च्या कमतरतेमुळे स्कर्व्ही होतो."},{"id":52,"subject":"Science","en":"Which instrument measures atmospheric pressure?","mr":"वातावरणाचा दाब मोजण्यासाठी कोणते उपकरण वापरतात?","options":["Barometer","Thermometer","Hygrometer","Ammeter"],"answer":0,"explanationEn":"A barometer measures atmospheric pressure.","explanationMr":"बॅरोमीटर वातावरणाचा दाब मोजतो."},{"id":53,"subject":"Science","en":"Which blood components are essential for clotting?","mr":"रक्त गोठण्यासाठी कोणते घटक महत्त्वाचे असतात?","options":["Platelets","Red blood cells","White blood cells","Plasma proteins only"],"answer":0,"explanationEn":"Platelets play a central role in forming the initial platelet plug.","explanationMr":"रक्त गोठण्याच्या सुरुवातीच्या प्रक्रियेत रक्तपट्टिका महत्त्वाची भूमिका बजावतात."},{"subject":"Economy","topic":"Banking","en":"Which institution issues currency notes in India, except the one-rupee note?","mr":"भारतात एक रुपयाची नोट वगळता चलनी नोटा कोणती संस्था जारी करते?","options":["Reserve Bank of India","State Bank of India","Ministry of Finance","SEBI"],"answer":0,"explanationEn":"The RBI issues banknotes in India; the one-rupee note is issued by the Government of India.","explanationMr":"भारतात रिझर्व्ह बँक नोटा जारी करते; एक रुपयाची नोट भारत सरकार जारी करते.","id":54},{"subject":"Economy","topic":"Banking","en":"Which rate is the traditional policy rate associated with RBI lending to commercial banks?","mr":"व्यावसायिक बँकांना RBI कर्ज देण्याशी संबंधित पारंपरिक धोरणात्मक दर कोणता?","options":["Bank Rate","GST rate","MSP","Exchange rate"],"answer":0,"explanationEn":"The Bank Rate is a monetary-policy rate associated with RBI lending to banks.","explanationMr":"बँक दर हा RBI च्या बँकांना कर्जपुरवठ्याशी संबंधित चलनविषयक धोरणात्मक दर आहे.","id":55},{"subject":"Economy","topic":"Public Finance","en":"Government spending on building a new highway is classified mainly as what?","mr":"नवीन महामार्ग बांधण्यासाठीचा सरकारी खर्च मुख्यतः कोणत्या प्रकारात मोडतो?","options":["Capital expenditure","Revenue expenditure","Transfer payment","Interest receipt"],"answer":0,"explanationEn":"Creating a durable public asset such as a highway is capital expenditure.","explanationMr":"महामार्गासारखी टिकाऊ सार्वजनिक मालमत्ता निर्माण करणे हा भांडवली खर्च आहे.","id":56},{"subject":"Economy","topic":"Inflation","en":"Demand-pull inflation is most directly associated with what situation?","mr":"मागणीजन्य महागाईचा सर्वात थेट संबंध कोणत्या परिस्थितीशी आहे?","options":["Aggregate demand rising faster than supply","A fall in consumer demand","A fall in money wages only","A rise in agricultural output"],"answer":0,"explanationEn":"Demand-pull inflation occurs when aggregate demand outpaces the economy's capacity to supply goods and services.","explanationMr":"एकूण मागणी वस्तू व सेवांच्या पुरवठा क्षमतेपेक्षा वेगाने वाढल्यास मागणीजन्य महागाई होते.","id":57},{"subject":"Economy","topic":"National Income","en":"Which measure values domestic production at current-year prices?","mr":"चालू वर्षाच्या किंमतींवर देशांतर्गत उत्पादनाचे मूल्य कोणते मापन दर्शवते?","options":["Nominal GDP","Real GDP","Per capita income","Human Development Index"],"answer":0,"explanationEn":"Nominal GDP measures output at current prices, so it includes the effect of price changes.","explanationMr":"नाममात्र GDP उत्पादनाचे मूल्य चालू किंमतींवर मोजतो; त्यामुळे किंमत बदलांचा परिणाम त्यात असतो.","id":58},{"subject":"Economy","topic":"External Sector","en":"A trade deficit occurs when a country's imports of goods exceed what?","mr":"देशाची वस्तूंची आयात कोणत्या बाबीपेक्षा जास्त झाल्यास व्यापार तूट निर्माण होते?","options":["Exports of goods","Government revenue","Foreign exchange reserves","Domestic savings"],"answer":0,"explanationEn":"A merchandise trade deficit occurs when the value of goods imports exceeds goods exports.","explanationMr":"वस्तूंच्या आयातीचे मूल्य वस्तूंच्या निर्यातीपेक्षा जास्त असल्यास व्यापार तूट होते.","id":59},{"subject":"Economy","topic":"Agriculture","en":"Which organisation recommends Minimum Support Prices for major crops to the Union Government?","mr":"प्रमुख पिकांच्या किमान आधारभूत किंमतींची केंद्र सरकारला शिफारस कोणती संस्था करते?","options":["Commission for Agricultural Costs and Prices","Food Corporation of India","NITI Aayog","NABARD"],"answer":0,"explanationEn":"The Commission for Agricultural Costs and Prices (CACP) recommends MSPs.","explanationMr":"कृषी खर्च आणि किंमत आयोग (CACP) MSP ची शिफारस करतो.","id":60},{"subject":"Economy","topic":"Labour","en":"Unemployment caused by a mismatch between workers' skills and available jobs is called what?","mr":"कामगारांच्या कौशल्यांचा उपलब्ध नोकऱ्यांशी मेळ न बसल्याने निर्माण होणाऱ्या बेरोजगारीला काय म्हणतात?","options":["Structural unemployment","Seasonal unemployment","Frictional unemployment","Disguised unemployment"],"answer":0,"explanationEn":"Structural unemployment arises when workers' skills or locations do not match available jobs.","explanationMr":"कामगारांची कौशल्ये किंवा ठिकाण उपलब्ध रोजगाराशी जुळत नसल्यास संरचनात्मक बेरोजगारी निर्माण होते.","id":61},{"subject":"Economy","topic":"Taxation","en":"Which tax is generally considered an indirect tax because its burden can be passed to consumers?","mr":"कराचा भार ग्राहकांवर पुढे ढकलता येतो म्हणून कोणता कर अप्रत्यक्ष कर मानला जातो?","options":["GST","Personal income tax","Corporate income tax","Wealth tax"],"answer":0,"explanationEn":"GST is an indirect tax on the supply of goods and services, generally collected through the supply chain.","explanationMr":"GST हा वस्तू व सेवांच्या पुरवठ्यावर आकारला जाणारा अप्रत्यक्ष कर आहे.","id":62},{"subject":"Economy","topic":"Banking","en":"What is the main purpose of the Cash Reserve Ratio (CRR)?","mr":"रोख राखीव प्रमाणाचा (CRR) मुख्य उद्देश काय आहे?","options":["To require banks to keep a prescribed cash balance with RBI","To insure every bank loan","To set the income tax slab","To finance state highways"],"answer":0,"explanationEn":"CRR requires banks to keep a specified share of their net demand and time liabilities as cash balances with the RBI.","explanationMr":"CRR नुसार बँकांना त्यांच्या निव्वळ मागणी व मुदत दायित्वांचा ठरावीक हिस्सा RBI कडे रोख स्वरूपात ठेवावा लागतो.","id":63},{"subject":"Current Affairs","topic":"Government Schemes","en":"What is the full name of the VISTAR scheme approved by the Union Cabinet on 4 November 2026?","mr":"४ नोव्हेंबर २०२६ रोजी केंद्रीय मंत्रिमंडळाने मंजूर केलेल्या VISTAR योजनेचे पूर्ण नाव काय?","options":["Viksit Bharat Initiative for Statistical Transformation, Analytics & Research","Vision for Integrated Science, Technology and Rural Affairs","Viksit India Scheme for Transport and Regional Roads","Village Information System for Trade and Agriculture"],"answer":0,"explanationEn":"PIB identifies VISTAR as the Viksit Bharat Initiative for Statistical Transformation, Analytics & Research.","explanationMr":"PIB नुसार VISTAR म्हणजे विकसित भारत इनिशिएटिव्ह फॉर स्टॅटिस्टिकल ट्रान्सफॉर्मेशन, अॅनालिटिक्स अँड रिसर्च.","id":64},{"subject":"Current Affairs","topic":"Government Schemes","en":"What is the approved outlay of the VISTAR scheme for 2026–27 to 2030–31?","mr":"२०२६–२७ ते २०३०–३१ या कालावधीसाठी VISTAR योजनेची मंजूर तरतूद किती आहे?","options":["₹4,371.10 crore","₹2,814 crore","₹14,500 crore","₹9,200 crore"],"answer":0,"explanationEn":"The Cabinet approved an outlay of ₹4,371.10 crore for VISTAR.","explanationMr":"VISTAR योजनेसाठी मंत्रिमंडळाने ₹४,३७१.१० कोटींची तरतूद मंजूर केली.","id":65},{"subject":"Current Affairs","topic":"Government Statistics","en":"VISTAR is designed primarily to strengthen which national capability?","mr":"VISTAR योजना प्रामुख्याने कोणती राष्ट्रीय क्षमता बळकट करण्यासाठी आहे?","options":["Official statistics, analytics and research systems","Defence exports","Urban metro construction","Crop insurance claims"],"answer":0,"explanationEn":"The scheme aims to modernise official statistics, surveys, research, data governance and digital systems.","explanationMr":"या योजनेचा उद्देश अधिकृत आकडेवारी, सर्वेक्षणे, संशोधन, डेटा प्रशासन आणि डिजिटल प्रणालींचे आधुनिकीकरण करणे आहे.","id":66},{"subject":"Current Affairs","topic":"Government Statistics","en":"Which area is explicitly included in the VISTAR scheme's modernisation agenda?","mr":"VISTAR योजनेच्या आधुनिकीकरणाच्या उद्दिष्टांमध्ये कोणत्या क्षेत्राचा स्पष्ट समावेश आहे?","options":["National data governance and harmonised datasets","Private insurance pricing only","Defence procurement only","Municipal property taxation only"],"answer":0,"explanationEn":"PIB describes national data governance and harmonised, AI-ready datasets as elements of VISTAR.","explanationMr":"राष्ट्रीय डेटा प्रशासन आणि सुसंगत, AI-सज्ज डेटासेट हे VISTAR चे घटक असल्याचे PIB नमूद करते.","id":67},{"subject":"Current Affairs","topic":"Critical Minerals","en":"The Cabinet's ₹2,814-crore capex support scheme announced on 4 November 2026 focuses on processing which minerals?","mr":"४ नोव्हेंबर २०२६ रोजी जाहीर ₹२,८१४ कोटींची भांडवली सहाय्य योजना कोणत्या खनिजांच्या प्रक्रियेवर केंद्रित आहे?","options":["Lithium and nickel","Iron and copper","Gold and silver","Coal and bauxite"],"answer":0,"explanationEn":"PIB states that the scheme promotes lithium and nickel processing.","explanationMr":"PIB नुसार ही योजना लिथियम आणि निकेल प्रक्रिया क्षमतेस प्रोत्साहन देते.","id":68},{"subject":"Current Affairs","topic":"Critical Minerals","en":"The critical-mineral processing scheme announced in November 2026 is structured as what kind of support?","mr":"नोव्हेंबर २०२६ मध्ये जाहीर महत्त्वपूर्ण खनिज प्रक्रिया योजना कोणत्या प्रकारचे सहाय्य देते?","options":["Capital expenditure support","Direct cash transfer to households","Crop price insurance","Interest-free student loans"],"answer":0,"explanationEn":"The Cabinet announcement describes a capex support scheme for lithium and nickel processing.","explanationMr":"मंत्रिमंडळाच्या घोषणेत लिथियम आणि निकेल प्रक्रिया क्षेत्रासाठी भांडवली खर्च सहाय्य योजनेचा उल्लेख आहे.","id":69},{"subject":"Current Affairs","topic":"Energy Storage","en":"What is the approved viability-gap funding outlay for grid-scale energy storage announced on 4 November 2026?","mr":"४ नोव्हेंबर २०२६ रोजी जाहीर ग्रिड-स्तरीय ऊर्जा साठवण योजनेसाठी मंजूर व्यवहार्यता तूट निधी किती आहे?","options":["₹14,500 crore","₹4,371.10 crore","₹2,814 crore","₹1,450 crore"],"answer":0,"explanationEn":"The Cabinet approved ₹14,500 crore in viability-gap funding for grid-scale energy storage systems.","explanationMr":"ग्रिड-स्तरीय ऊर्जा साठवण प्रणालींसाठी मंत्रिमंडळाने ₹१४,५०० कोटींच्या व्यवहार्यता तूट निधीस मंजुरी दिली.","id":70},{"subject":"Current Affairs","topic":"Energy Storage","en":"What grid-scale energy storage capacity is targeted under the November 2026 VGF scheme?","mr":"नोव्हेंबर २०२६ मधील VGF योजनेत किती ग्रिड-स्तरीय ऊर्जा साठवण क्षमता उद्दिष्टित आहे?","options":["92 GWh","9.2 GWh","29 GWh","920 GWh"],"answer":0,"explanationEn":"The scheme is intended to support 92 GWh of grid-scale energy storage systems.","explanationMr":"या योजनेत ९२ GWh क्षमतेच्या ग्रिड-स्तरीय ऊर्जा साठवण प्रणालींना सहाय्य देण्याचे उद्दिष्ट आहे.","id":71},{"subject":"Current Affairs","topic":"Energy Storage","en":"What does VGF stand for in the grid-scale energy storage scheme?","mr":"ग्रिड ऊर्जा साठवण योजनेतील VGF चे पूर्ण रूप काय आहे?","options":["Viability Gap Funding","Variable Grid Frequency","Verified Generation Fund","Village Green Fund"],"answer":0,"explanationEn":"VGF stands for Viability Gap Funding, a form of support for projects that may not be commercially viable on their own.","explanationMr":"VGF म्हणजे Viability Gap Funding; स्वतंत्रपणे व्यावसायिकदृष्ट्या व्यवहार्य नसलेल्या प्रकल्पांना दिले जाणारे सहाय्य.","id":72},{"subject":"Current Affairs","topic":"Justice","en":"The Union Cabinet continued the Fast Track Special Courts scheme in November 2026 for expeditious trials under which laws?","mr":"नोव्हेंबर २०२६ मध्ये केंद्रीय मंत्रिमंडळाने कोणत्या कायद्यांतील खटल्यांच्या जलद सुनावणीसाठी फास्ट ट्रॅक विशेष न्यायालय योजना पुढे सुरू ठेवली?","options":["Rape and POCSO cases","Tax evasion and customs cases","Motor vehicle challans","Land revenue disputes"],"answer":0,"explanationEn":"The Cabinet continued the Centrally Sponsored FTSC scheme for expeditious trial of rape and POCSO cases.","explanationMr":"बलात्कार आणि POCSO प्रकरणांच्या जलद सुनावणीसाठी केंद्र पुरस्कृत FTSC योजना पुढे सुरू ठेवण्यास मंत्रिमंडळाने मंजुरी दिली.","id":73},{"subject":"Current Affairs","topic":"Urban Transport","en":"The Aqua Line extension approved in November 2026 connects Noida Sector-51 with which station?","mr":"नोव्हेंबर २०२६ मध्ये मंजूर ॲक्वा लाइन विस्तार नोएडा सेक्टर-५१ ला कोणत्या स्थानकाशी जोडतो?","options":["Greater Noida Sector-04","Greater Noida Sector-10","Noida Sector-18","Ghaziabad Railway Station"],"answer":0,"explanationEn":"The approved extension runs from Noida Sector-51 to Greater Noida Sector-04.","explanationMr":"मंजूर विस्तार नोएडा सेक्टर-५१ ते ग्रेटर नोएडा सेक्टर-०४ असा आहे.","id":74},{"subject":"Current Affairs","topic":"Urban Transport","en":"What is the route length of the Aqua Line extension approved by the Cabinet on 11 November 2026?","mr":"११ नोव्हेंबर २०२६ रोजी मंत्रिमंडळाने मंजूर केलेल्या ॲक्वा लाइन विस्ताराची लांबी किती आहे?","options":["8.449 km","5.5 km","14.5 km","18.449 km"],"answer":0,"explanationEn":"The approved Aqua Line extension has a route length of 8.449 km.","explanationMr":"मंजूर ॲक्वा लाइन विस्ताराची मार्गलांबी ८.४४९ किमी आहे.","id":75},{"subject":"Current Affairs","topic":"Urban Transport","en":"How many stations are planned on the approved Aqua Line extension from Noida Sector-51 to Greater Noida Sector-04?","mr":"नोएडा सेक्टर-५१ ते ग्रेटर नोएडा सेक्टर-०४ या मंजूर ॲक्वा लाइन विस्तारावर किती स्थानके आहेत?","options":["5","4","6","8"],"answer":0,"explanationEn":"The Cabinet release specifies five stations on the 8.449-km extension.","explanationMr":"मंत्रिमंडळाच्या प्रसिद्धिपत्रकात ८.४४९ किमी विस्तारावर पाच स्थानकांचा उल्लेख आहे.","id":76},{"subject":"Current Affairs","topic":"Space","en":"Which satellite was launched by GSLV-F18 on 30 October 2026?","mr":"३० ऑक्टोबर २०२६ रोजी GSLV-F18 ने कोणता उपग्रह प्रक्षेपित केला?","options":["NVS-03","EOS-05","NVS-02","NISAR"],"answer":0,"explanationEn":"ISRO identifies NVS-03 as the payload of the GSLV-F18 mission.","explanationMr":"ISRO नुसार GSLV-F18 मोहिमेचा उपभार NVS-03 होता.","id":77},{"subject":"Current Affairs","topic":"Space","en":"NVS-03 is part of which Indian satellite system?","mr":"NVS-03 हा भारताच्या कोणत्या उपग्रह प्रणालीचा भाग आहे?","options":["NavIC / IRNSS navigation system","INSAT communication system","Cartosat mapping system","RISAT radar imaging system"],"answer":0,"explanationEn":"NVS-03 is the third satellite in the next-generation navigation system intended to continue IRNSS/NavIC services.","explanationMr":"IRNSS/NavIC सेवा सुरू ठेवण्यासाठीच्या पुढील पिढीच्या नेव्हिगेशन प्रणालीतील NVS-03 हा तिसरा उपग्रह आहे.","id":78},{"subject":"Current Affairs","topic":"Space","en":"Which indigenous technology is carried aboard NVS-03, according to ISRO?","mr":"ISRO च्या माहितीनुसार NVS-03 वर कोणते स्वदेशी तंत्रज्ञान आहे?","options":["Indigenous atomic clock","Reusable cryogenic engine","Crew escape tower","Synthetic-aperture radar"],"answer":0,"explanationEn":"ISRO states that NVS-03 carries an indigenous atomic clock along with procured clocks.","explanationMr":"ISRO नुसार NVS-03 वर आयात केलेल्या घड्याळांसह स्वदेशी अणुघड्याळ आहे.","id":79},{"subject":"Current Affairs","topic":"Agriculture","en":"The Rabi 2026–27 Nutrient Based Subsidy rates approved in November 2026 apply to which period?","mr":"नोव्हेंबर २०२६ मध्ये मंजूर रब्बी २०२६–२७ पोषक तत्त्वाधारित अनुदान दर कोणत्या कालावधीस लागू आहेत?","options":["1 October 2026 to 31 March 2027","1 April 2026 to 30 September 2026","1 January 2027 to 31 December 2027","1 July 2026 to 30 June 2027"],"answer":0,"explanationEn":"The approved rates apply from 1 October 2026 through 31 March 2027.","explanationMr":"मंजूर दर १ ऑक्टोबर २०२६ ते ३१ मार्च २०२७ या कालावधीत लागू आहेत.","id":80},{"subject":"Current Affairs","topic":"Entrepreneurship","en":"Which scheme's continuation did the Union Cabinet approve on 11 November 2026?","mr":"११ नोव्हेंबर २०२६ रोजी केंद्रीय मंत्रिमंडळाने कोणती योजना पुढे सुरू ठेवण्यास मंजुरी दिली?","options":["Stand-Up India","PM-KISAN","UDAN","PMGSY"],"answer":0,"explanationEn":"PIB listed Cabinet approval for continuation of the Stand-Up India Scheme on 11 November 2026.","explanationMr":"PIB च्या ११ नोव्हेंबर २०२६ च्या नोंदीत Stand-Up India योजना पुढे सुरू ठेवण्यास मंजुरी दिल्याचे नमूद आहे.","id":81},{"subject":"Current Affairs","topic":"Credit","en":"Which fund's continuation was approved by the Union Cabinet on 11 November 2026 for micro units?","mr":"सूक्ष्म घटकांसाठी कोणता निधी ११ नोव्हेंबर २०२६ रोजी पुढे सुरू ठेवण्यास केंद्रीय मंत्रिमंडळाने मंजुरी दिली?","options":["Credit Guarantee Fund for Micro Units","National Clean Energy Fund","Central Road Fund","National Investment Fund"],"answer":0,"explanationEn":"The Cabinet approved continuation of the Credit Guarantee Fund for Micro Units.","explanationMr":"सूक्ष्म घटकांसाठीच्या पत हमी निधीचे सातत्य राखण्यास मंत्रिमंडळाने मंजुरी दिली.","id":82},{"subject":"Current Affairs","topic":"Space","en":"On what date did ISRO report that NVS-03 had been successfully injected into orbit by GSLV?","mr":"GSLV ने NVS-03 ला कक्षेत यशस्वीरीत्या सोडल्याची ISRO ने कोणत्या तारखेला नोंद केली?","options":["30 October 2026","4 September 2026","29 January 2025","31 October 2026"],"answer":0,"explanationEn":"ISRO's mission record states that GSLV-F18 injected NVS-03 on 30 October 2026.","explanationMr":"ISRO च्या मोहिमेच्या नोंदीनुसार GSLV-F18 ने ३० ऑक्टोबर २०२६ रोजी NVS-03 ला कक्षेत सोडले.","id":83},{"subject":"Current Affairs","topic":"Space","en":"What additional navigation signal band does NVS-03 include besides L5 and S bands?","mr":"L5 आणि S बँड व्यतिरिक्त NVS-03 मध्ये कोणता अतिरिक्त नेव्हिगेशन सिग्नल बँड आहे?","options":["L1","C band","Ku band","X band"],"answer":0,"explanationEn":"ISRO states that NVS-03 includes the L1 signal in addition to L5 and S-band signals.","explanationMr":"ISRO नुसार NVS-03 मध्ये L5 आणि S-बँड व्यतिरिक्त L1 सिग्नलही आहे.","id":84},{"subject":"Polity","topic":"Constitution","en":"Which Article provides for the Attorney General of India?","mr":"भारताच्या महान्यायवादी पदाची तरतूद कोणत्या कलमात आहे?","options":["Article 76","Article 165","Article 148","Article 280"],"answer":0,"explanationEn":"Article 76 provides for the Attorney General of India.","explanationMr":"कलम ७६ मध्ये भारताच्या महान्यायवादी पदाची तरतूद आहे.","id":85},{"subject":"Polity","topic":"Parliament","en":"What is the maximum gap permitted between two sessions of Parliament?","mr":"संसदेच्या दोन अधिवेशनांमध्ये जास्तीत जास्त किती अंतर असू शकते?","options":["Six months","Three months","Nine months","One year"],"answer":0,"explanationEn":"The Constitution requires that six months should not intervene between the last sitting of one session and the first sitting of the next.","explanationMr":"एका अधिवेशनाच्या शेवटच्या बैठकीपासून पुढील अधिवेशनाच्या पहिल्या बैठकीपर्यंत सहा महिन्यांपेक्षा जास्त अंतर असू शकत नाही.","id":86},{"subject":"Polity","topic":"State Government","en":"Who appoints the Chief Minister of a State?","mr":"राज्याच्या मुख्यमंत्र्यांची नियुक्ती कोण करतात?","options":["Governor","President","Chief Justice of the High Court","Speaker"],"answer":0,"explanationEn":"The Governor appoints the Chief Minister under Article 164.","explanationMr":"कलम १६४ नुसार राज्यपाल मुख्यमंत्र्यांची नियुक्ती करतात.","id":87},{"subject":"Polity","topic":"Judiciary","en":"Which court is the highest court of appeal in India?","mr":"भारतातील सर्वोच्च अपील न्यायालय कोणते?","options":["Supreme Court of India","High Court","District Court","National Green Tribunal"],"answer":0,"explanationEn":"The Supreme Court is the apex judicial authority in India.","explanationMr":"भारताचे सर्वोच्च न्यायालय हे देशातील सर्वोच्च न्यायिक प्राधिकरण आहे.","id":88},{"subject":"Polity","topic":"Fundamental Rights","en":"Which Article abolishes untouchability?","mr":"अस्पृश्यता नष्ट करणारे कलम कोणते?","options":["Article 17","Article 14","Article 19","Article 21"],"answer":0,"explanationEn":"Article 17 abolishes untouchability and forbids its practice in any form.","explanationMr":"कलम १७ अस्पृश्यता नष्ट करते आणि तिच्या कोणत्याही स्वरूपातील आचरणास मनाई करते.","id":89},{"subject":"Polity","topic":"Local Government","en":"The Eleventh Schedule is associated with which institutions?","mr":"अकरावी अनुसूची कोणत्या संस्थांशी संबंधित आहे?","options":["Panchayats","Municipalities","Parliament","High Courts"],"answer":0,"explanationEn":"The Eleventh Schedule lists subjects that may be devolved to Panchayats.","explanationMr":"अकराव्या अनुसूचीत पंचायतींकडे सोपवता येणारे विषय नमूद आहेत.","id":90},{"subject":"Polity","topic":"Local Government","en":"The Twelfth Schedule lists functions of which bodies?","mr":"बाराव्या अनुसूचीत कोणत्या संस्थांची कार्ये दिली आहेत?","options":["Municipalities","Panchayats","State Legislatures","Public Service Commissions"],"answer":0,"explanationEn":"The Twelfth Schedule lists functions of municipalities under the 74th Amendment framework.","explanationMr":"७४ व्या घटनादुरुस्तीच्या चौकटीत बाराव्या अनुसूचीत नगरपालिकांची कार्ये दिली आहेत.","id":91},{"subject":"Polity","topic":"Constitution","en":"Which Part of the Constitution contains the Directive Principles of State Policy?","mr":"राज्याच्या धोरणाची मार्गदर्शक तत्त्वे संविधानाच्या कोणत्या भागात आहेत?","options":["Part IV","Part III","Part V","Part IVA"],"answer":0,"explanationEn":"Directive Principles of State Policy are contained in Part IV, Articles 36–51.","explanationMr":"राज्याच्या धोरणाची मार्गदर्शक तत्त्वे भाग IV, कलम ३६ ते ५१ मध्ये आहेत.","id":92},{"subject":"Polity","topic":"Constitution","en":"Which Article provides for the annual financial statement, commonly called the Union Budget?","mr":"अर्थसंकल्प म्हणून ओळखल्या जाणाऱ्या वार्षिक वित्तीय विवरणपत्राची तरतूद कोणत्या कलमात आहे?","options":["Article 112","Article 110","Article 123","Article 280"],"answer":0,"explanationEn":"Article 112 provides for the annual financial statement of the Government of India.","explanationMr":"कलम ११२ भारत सरकारच्या वार्षिक वित्तीय विवरणपत्राची तरतूद करते.","id":93},{"subject":"Polity","topic":"State Legislature","en":"A State Legislative Council can be created or abolished by Parliament under which Article?","mr":"राज्य विधानपरिषदेची निर्मिती किंवा रद्दबातल करण्याची संसदेला परवानगी कोणत्या कलमाने दिली आहे?","options":["Article 169","Article 168","Article 170","Article 172"],"answer":0,"explanationEn":"Article 169 provides the procedure for creation or abolition of a State Legislative Council.","explanationMr":"कलम १६९ राज्य विधानपरिषदेची निर्मिती किंवा रद्द करण्याची प्रक्रिया सांगते.","id":94},{"subject":"Science","topic":"Physics","en":"Which lens is used to correct myopia (short-sightedness)?","mr":"निकटदृष्टी दोष (मायोपिया) सुधारण्यासाठी कोणती भिंग वापरतात?","options":["Concave lens","Convex lens","Cylindrical lens only","Bifocal lens only"],"answer":0,"explanationEn":"A concave lens diverges incoming light so the image forms on the retina for a myopic eye.","explanationMr":"अंतर्गोल भिंग प्रकाशकिरणे अपसारी करून मायोपिया असलेल्या डोळ्यात प्रतिमा दृष्टिपटलावर तयार होण्यास मदत करते.","id":95},{"subject":"Science","topic":"Chemistry","en":"What is the chemical symbol of sodium?","mr":"सोडियमचे रासायनिक चिन्ह कोणते?","options":["Na","So","S","Sd"],"answer":0,"explanationEn":"Na is the symbol for sodium, derived from the Latin natrium.","explanationMr":"Na हे सोडियमचे चिन्ह असून ते लॅटिन natrium या नावावरून आले आहे.","id":96},{"subject":"Science","topic":"Biology","en":"Which gland is commonly called the master gland of the endocrine system?","mr":"अंतःस्रावी संस्थेची प्रमुख ग्रंथी म्हणून कोणती ग्रंथी ओळखली जाते?","options":["Pituitary gland","Thyroid gland","Adrenal gland","Pancreas"],"answer":0,"explanationEn":"The pituitary gland releases hormones that regulate several other endocrine glands.","explanationMr":"पीयूषिका ग्रंथी अनेक इतर अंतःस्रावी ग्रंथींचे नियमन करणारी संप्रेरके स्रवते.","id":97},{"subject":"Science","topic":"Physics","en":"What is the SI unit of power?","mr":"शक्तीचे SI एकक कोणते?","options":["Watt","Joule","Newton","Pascal"],"answer":0,"explanationEn":"Power is the rate of transfer or use of energy and is measured in watts.","explanationMr":"ऊर्जेच्या वापराचा किंवा हस्तांतरणाचा दर म्हणजे शक्ती; तिचे एकक वॅट आहे.","id":98},{"subject":"Science","topic":"Chemistry","en":"A solution with pH 3 is best described as what?","mr":"pH ३ असलेले द्रावण कसे वर्णन केले जाते?","options":["Acidic","Neutral","Alkaline","Always a salt"],"answer":0,"explanationEn":"A pH below 7 is acidic at ordinary reference conditions.","explanationMr":"सामान्य संदर्भस्थितीत pH ७ पेक्षा कमी असल्यास द्रावण आम्लधर्मी असते.","id":99},{"subject":"Science","topic":"Environment","en":"Which gas is a major contributor to human-caused global warming?","mr":"मानवनिर्मित जागतिक तापमानवाढीस मोठा हातभार लावणारा वायू कोणता?","options":["Carbon dioxide","Helium","Neon","Hydrogen"],"answer":0,"explanationEn":"Carbon dioxide is a major long-lived greenhouse gas emitted by fossil-fuel use and land-use change.","explanationMr":"जीवाश्म इंधन वापर आणि जमीन-वापर बदलांमुळे उत्सर्जित होणारा कार्बन डायऑक्साइड हा प्रमुख दीर्घायुषी हरितगृह वायू आहे.","id":100},{"subject":"Maths","topic":"Percentages","en":"What is 15% of 840?","mr":"८४० चे १५% किती?","options":["126","124","128","132"],"answer":0,"explanationEn":"10% of 840 is 84 and 5% is 42; total = 126.","explanationMr":"८४० चे १०% = ८४ आणि ५% = ४२; एकूण १२६.","id":101},{"subject":"Maths","topic":"Profit and Loss","en":"An article is bought for ₹800 and sold for ₹1,000. What is the profit percentage?","mr":"₹८०० ला घेतलेली वस्तू ₹१,००० ला विकली. नफ्याची टक्केवारी किती?","options":["25%","20%","22.5%","30%"],"answer":0,"explanationEn":"Profit = ₹200; profit percentage = 200/800 × 100 = 25%.","explanationMr":"नफा ₹२००; नफ्याची टक्केवारी = २००/८०० × १०० = २५%.","id":102},{"subject":"Maths","topic":"Discount","en":"A marked price of ₹1,500 is reduced by 12%. Find the sale price.","mr":"₹१,५०० छापील किंमतीवर १२% सूट दिली. विक्री किंमत किती?","options":["₹1,320","₹1,300","₹1,350","₹1,280"],"answer":0,"explanationEn":"Discount = ₹180, so sale price = ₹1,320.","explanationMr":"सूट ₹१८०; विक्री किंमत ₹१,३२०.","id":103},{"subject":"Maths","topic":"Ratio","en":"Divide ₹720 in the ratio 2:3:4. What is the largest share?","mr":"₹७२० ची २:३:४ या प्रमाणात विभागणी केल्यास सर्वांत मोठा हिस्सा किती?","options":["₹320","₹240","₹280","₹360"],"answer":0,"explanationEn":"Total parts = 9; one part = ₹80; largest share = ₹320.","explanationMr":"एकूण भाग ९; एक भाग ₹८०; मोठा हिस्सा ₹३२०.","id":104},{"subject":"Maths","topic":"Average","en":"The average of 14, 18, 22, 26 and 30 is what?","mr":"१४, १८, २२, २६ आणि ३० यांची सरासरी किती?","options":["22","20","21","24"],"answer":0,"explanationEn":"The sum is 110; 110 ÷ 5 = 22.","explanationMr":"बेरीज ११०; ११० ÷ ५ = २२.","id":105},{"subject":"Maths","topic":"Simple Interest","en":"Find the simple interest on ₹6,000 at 8% per annum for 3 years.","mr":"₹६,००० वर वार्षिक ८% दराने ३ वर्षांचे सरळ व्याज किती?","options":["₹1,440","₹1,200","₹1,600","₹1,480"],"answer":0,"explanationEn":"SI = PRT/100 = ₹1,440.","explanationMr":"सरळ व्याज = ६००० × ८ × ३ ÷ १०० = ₹१,४४०.","id":106},{"subject":"Maths","topic":"Time and Work","en":"A can complete a task in 10 days and B in 15 days. How many days do they need together?","mr":"A काम १० दिवसांत आणि B १५ दिवसांत करतो. दोघे मिळून किती दिवसांत करतील?","options":["6 days","5 days","7 days","8 days"],"answer":0,"explanationEn":"Combined work per day = 1/10 + 1/15 = 1/6; time = 6 days.","explanationMr":"दैनंदिन एकत्रित काम = १/१० + १/१५ = १/६; वेळ ६ दिवस.","id":107},{"subject":"Maths","topic":"Speed and Distance","en":"A car travels 210 km in 3.5 hours. Find its average speed.","mr":"कार ३.५ तासांत २१० किमी जाते. सरासरी वेग किती?","options":["60 km/h","55 km/h","65 km/h","70 km/h"],"answer":0,"explanationEn":"Speed = 210 ÷ 3.5 = 60 km/h.","explanationMr":"वेग = २१० ÷ ३.५ = ६० किमी/तास.","id":108},{"subject":"Maths","topic":"Number System","en":"What is the HCF of 96 and 144?","mr":"९६ आणि १४४ यांचा म.सा.वि. किती?","options":["48","24","36","72"],"answer":0,"explanationEn":"The greatest common factor of 96 and 144 is 48.","explanationMr":"९६ आणि १४४ यांचा म.सा.वि. ४८ आहे.","id":109},{"subject":"Maths","topic":"Fractions","en":"Simplify 3/4 + 5/8.","mr":"३/४ + ५/८ यांची बेरीज सोपी करा.","options":["11/8","8/12","9/8","7/8"],"answer":0,"explanationEn":"3/4 = 6/8, so 6/8 + 5/8 = 11/8.","explanationMr":"३/४ = ६/८; म्हणून बेरीज ११/८.","id":110},{"subject":"Maths","topic":"Mensuration","en":"Find the area of a triangle with base 12 cm and height 9 cm.","mr":"पाया १२ सेमी आणि उंची ९ सेमी असलेल्या त्रिकोणाचे क्षेत्रफळ किती?","options":["54 cm²","108 cm²","48 cm²","42 cm²"],"answer":0,"explanationEn":"Area = 1/2 × 12 × 9 = 54 cm².","explanationMr":"क्षेत्रफळ = १/२ × १२ × ९ = ५४ चौ.सेमी.","id":111},{"subject":"Maths","topic":"Algebra","en":"If 3x − 7 = 20, what is x?","mr":"३x − ७ = २० असल्यास x किती?","options":["9","7","8","10"],"answer":0,"explanationEn":"3x = 27, therefore x = 9.","explanationMr":"३x = २७; म्हणून x = ९.","id":112},{"subject":"Maths","topic":"Ratio and Proportion","en":"If 6 notebooks cost ₹90, how much will 14 notebooks cost at the same rate?","mr":"६ वह्यांची किंमत ₹९० असल्यास त्याच दराने १४ वह्यांची किंमत किती?","options":["₹210","₹200","₹220","₹240"],"answer":0,"explanationEn":"One notebook costs ₹15; 14 notebooks cost ₹210.","explanationMr":"एका वहीची किंमत ₹१५; १४ वह्यांची किंमत ₹२१०.","id":113},{"subject":"Maths","topic":"Ages","en":"A father is three times as old as his son. After 10 years he will be twice the son's age. How old is the son now?","mr":"वडिलांचे वय मुलाच्या वयाच्या तिप्पट आहे. १० वर्षांनी वडील मुलाच्या वयाच्या दुप्पट असतील. मुलाचे सध्याचे वय किती?","options":["10 years","12 years","15 years","20 years"],"answer":0,"explanationEn":"Let son's age be x. 3x + 10 = 2(x + 10), so x = 10.","explanationMr":"मुलाचे वय x धरल्यास ३x + १० = २(x + १०); म्हणून x = १०.","id":114},{"subject":"Maths","topic":"Compound Interest","en":"Find the compound interest on ₹2,000 for 2 years at 5% per annum, compounded annually.","mr":"₹२,००० वर वार्षिक ५% दराने २ वर्षांचे वार्षिक चक्रवाढ व्याज किती?","options":["₹205","₹200","₹210","₹220"],"answer":0,"explanationEn":"Amount = ₹2,205; compound interest = ₹205.","explanationMr":"मिश्रधन ₹२,२०५; चक्रवाढ व्याज ₹२०५.","id":115},{"subject":"Maths","topic":"Pipes and Cisterns","en":"A pipe fills a tank in 8 hours and a leak empties it in 24 hours. How long will it take to fill the tank when both act together?","mr":"एक नळ टाकी ८ तासांत भरतो आणि गळती २४ तासांत रिकामी करते. दोन्ही एकत्र असताना टाकी किती वेळात भरेल?","options":["12 hours","10 hours","14 hours","16 hours"],"answer":0,"explanationEn":"Net rate = 1/8 − 1/24 = 1/12 tank per hour; time = 12 hours.","explanationMr":"निव्वळ दर = १/८ − १/२४ = ताशी १/१२ टाकी; वेळ १२ तास.","id":116},{"subject":"Maths","topic":"Trains","en":"A 120 m train crosses a pole in 8 seconds. Find its speed in km/h.","mr":"१२० मीटर लांबीची रेल्वे ८ सेकंदांत खांब ओलांडते. वेग किमी/तासात किती?","options":["54 km/h","48 km/h","60 km/h","72 km/h"],"answer":0,"explanationEn":"Speed = 120/8 = 15 m/s = 54 km/h.","explanationMr":"वेग = १२०/८ = १५ मी/से = ५४ किमी/तास.","id":117},{"subject":"Maths","topic":"Mixtures","en":"A 20-litre mixture contains milk and water in the ratio 3:1. How much water is present?","mr":"२० लिटर मिश्रणात दूध आणि पाणी यांचे प्रमाण ३:१ आहे. पाण्याचे प्रमाण किती?","options":["5 litres","4 litres","6 litres","8 litres"],"answer":0,"explanationEn":"Water = 1/4 × 20 = 5 litres.","explanationMr":"पाणी = १/४ × २० = ५ लिटर.","id":118},{"subject":"Maths","topic":"Partnership","en":"A invests ₹5,000 for 12 months and B invests ₹8,000 for 6 months. In what ratio should profit be shared?","mr":"A ₹५,००० बारा महिने आणि B ₹८,००० सहा महिने गुंतवतो. नफ्याचे प्रमाण किती?","options":["5:4","4:5","3:4","5:6"],"answer":0,"explanationEn":"Capital × time gives 60,000:48,000 = 5:4.","explanationMr":"भांडवल × वेळ = ६०,०००:४८,००० = ५:४.","id":119},{"subject":"Maths","topic":"Geometry","en":"The angles of a triangle are in the ratio 2:3:4. Find the largest angle.","mr":"त्रिकोणाचे कोन २:३:४ या प्रमाणात आहेत. सर्वांत मोठा कोन किती?","options":["80°","60°","70°","90°"],"answer":0,"explanationEn":"Each part is 180°/9 = 20°; largest = 4 × 20° = 80°.","explanationMr":"एक भाग २०°; मोठा कोन ४ × २०° = ८०°.","id":120},{"subject":"Maths","topic":"Successive Percentages","en":"A price rises by 20% and then falls by 10%. What is the net percentage change?","mr":"किंमत प्रथम २०% वाढते आणि नंतर १०% घटते. निव्वळ टक्केवारीतील बदल किती?","options":["8% increase","10% increase","8% decrease","10% decrease"],"answer":0,"explanationEn":"100 × 1.20 × 0.90 = 108, an 8% increase.","explanationMr":"१०० × १.२० × ०.९० = १०८; म्हणजे ८% वाढ.","id":121},{"subject":"Maths","topic":"Work Rates","en":"12 workers complete a job in 15 days. How many days will 20 equally productive workers take?","mr":"१२ कामगार एक काम १५ दिवसांत करतात. समान कार्यक्षमतेचे २० कामगार ते किती दिवसांत करतील?","options":["9 days","8 days","10 days","12 days"],"answer":0,"explanationEn":"Work = 12 × 15 = 180 worker-days; 180/20 = 9 days.","explanationMr":"काम = १२ × १५ = १८० कामगार-दिवस; १८०/२० = ९ दिवस.","id":122},{"subject":"Maths","topic":"Divisibility","en":"What is the smallest number that must be added to 563 to make it divisible by 9?","mr":"५६३ ला ९ ने पूर्ण भाग जाण्यासाठी सर्वांत कमी किती संख्या मिळवावी?","options":["4","3","5","6"],"answer":0,"explanationEn":"Adding 4 gives 567, which is divisible by 9.","explanationMr":"४ मिळवल्यास ५६७ तयार होते आणि त्याला ९ ने भाग जातो.","id":123},{"subject":"Maths","topic":"Time and Distance","en":"Two cars start from the same point in opposite directions at 45 km/h and 55 km/h. How far apart are they after 2 hours?","mr":"दोन कार एकाच ठिकाणाहून विरुद्ध दिशांनी ४५ व ५५ किमी/तास वेगाने निघतात. २ तासांनी त्यांतील अंतर किती?","options":["200 km","180 km","190 km","220 km"],"answer":0,"explanationEn":"Relative speed = 100 km/h; distance in 2 hours = 200 km.","explanationMr":"सापेक्ष वेग = १०० किमी/तास; २ तासांत अंतर २०० किमी.","id":124},{"subject":"Maths","topic":"Data Interpretation","en":"A shop sold 120, 150 and 180 units in three months. What was the average monthly sale?","mr":"एका दुकानाने तीन महिन्यांत १२०, १५० आणि १८० वस्तू विकल्या. सरासरी मासिक विक्री किती?","options":["150 units","140 units","160 units","155 units"],"answer":0,"explanationEn":"Average = (120 + 150 + 180)/3 = 150.","explanationMr":"सरासरी = (१२० + १५० + १८०)/३ = १५०.","id":125},{"subject":"Maths","topic":"Number System","en":"What is the least common multiple of 8, 12 and 18?","mr":"८, १२ आणि १८ यांचा ल.सा.वि. किती?","options":["72","36","144","48"],"answer":0,"explanationEn":"LCM = 2³ × 3² = 72.","explanationMr":"ल.सा.वि. = २³ × ३² = ७२.","id":126},{"subject":"Maths","topic":"Work and Wages","en":"If 8 men earn ₹4,800 in 6 days, how much will 5 men earn in 4 days at the same rate?","mr":"८ पुरुष ६ दिवसांत ₹४,८०० कमावतात. त्याच दराने ५ पुरुष ४ दिवसांत किती कमावतील?","options":["₹2,000","₹1,800","₹2,400","₹2,200"],"answer":0,"explanationEn":"Per man-day earning = ₹100; 5 × 4 × 100 = ₹2,000.","explanationMr":"प्रति कामगार-दिवस उत्पन्न ₹१००; ५ × ४ × १०० = ₹२,०००.","id":127},{"subject":"Maths","topic":"Algebra","en":"If x + y = 12 and x − y = 4, find x.","mr":"x + y = १२ आणि x − y = ४ असल्यास x किती?","options":["8","6","4","10"],"answer":0,"explanationEn":"Adding the equations gives 2x = 16, so x = 8.","explanationMr":"दोन्ही समीकरणे मिळवल्यास २x = १६; म्हणून x = ८.","id":128},{"subject":"Maths","topic":"Mensuration","en":"Find the volume of a cube whose side is 5 cm.","mr":"५ सेमी बाजू असलेल्या घनाचे घनफळ किती?","options":["125 cm³","25 cm³","100 cm³","150 cm³"],"answer":0,"explanationEn":"Volume = side³ = 125 cm³.","explanationMr":"घनफळ = बाजू³ = १२५ घन सेमी.","id":129},{"subject":"Maths","topic":"Geometry","en":"A rectangle has length 18 cm and breadth 7 cm. Find its perimeter.","mr":"आयताची लांबी १८ सेमी व रुंदी ७ सेमी आहे. परिमिती किती?","options":["50 cm","25 cm","126 cm","42 cm"],"answer":0,"explanationEn":"Perimeter = 2(18 + 7) = 50 cm.","explanationMr":"परिमिती = २(१८ + ७) = ५० सेमी.","id":130},{"subject":"Reasoning","topic":"Number Series","en":"Find the next number: 4, 9, 16, 25, 36, __.","mr":"पुढील संख्या शोधा: ४, ९, १६, २५, ३६, __.","options":["49","45","48","64"],"answer":0,"explanationEn":"These are squares 2² through 6²; the next is 7² = 49.","explanationMr":"या २² ते ६² वर्गसंख्या आहेत; पुढील ७² = ४९.","id":131},{"subject":"Reasoning","topic":"Number Series","en":"Find the missing number: 2, 5, 10, 17, 26, __.","mr":"गाळलेली संख्या शोधा: २, ५, १०, १७, २६, __.","options":["37","35","36","39"],"answer":0,"explanationEn":"Differences are 3, 5, 7, 9; next difference is 11, giving 37.","explanationMr":"फरक ३, ५, ७, ९; पुढील फरक ११, म्हणून ३७.","id":132},{"subject":"Reasoning","topic":"Coding","en":"If TABLE is coded as UBCMF by shifting each letter one step forward, how is CHAIR coded?","mr":"TABLE चे UBCMF असे कूट केल्यास CHAIR चे कूट काय?","options":["DIBJS","DIBJR","DHBJS","DICJS"],"answer":0,"explanationEn":"Move each letter one step forward: C-D, H-I, A-B, I-J, R-S.","explanationMr":"प्रत्येक अक्षर एक स्थान पुढे: C-D, H-I, A-B, I-J, R-S.","id":133},{"subject":"Reasoning","topic":"Direction","en":"A person faces north, turns right, then left, then left again. Which direction is the person facing?","mr":"एक व्यक्ती उत्तरेकडे तोंड करून उजवीकडे, मग डावीकडे आणि पुन्हा डावीकडे वळते. आता ती कोणत्या दिशेला आहे?","options":["West","East","North","South"],"answer":0,"explanationEn":"North → East → North → West.","explanationMr":"उत्तर → पूर्व → उत्तर → पश्चिम.","id":134},{"subject":"Reasoning","topic":"Odd Pair","en":"Choose the odd pair: 3:9, 4:16, 5:25, 6:30.","mr":"विसंगत जोडी निवडा: ३:९, ४:१६, ५:२५, ६:३०.","options":["6:30","3:9","4:16","5:25"],"answer":0,"explanationEn":"The second number is the square of the first in three pairs; 6² is 36, not 30.","explanationMr":"तीन जोड्यांत दुसरी संख्या पहिल्याचा वर्ग आहे; ६² = ३६, ३० नाही.","id":135},{"subject":"Reasoning","topic":"Analogy","en":"Complete the analogy: Doctor : Hospital :: Teacher : __.","mr":"संबंध पूर्ण करा: डॉक्टर : रुग्णालय :: शिक्षक : __.","options":["School","Court","Bank","Farm"],"answer":0,"explanationEn":"A doctor commonly works in a hospital; a teacher commonly works in a school.","explanationMr":"डॉक्टर रुग्णालयात आणि शिक्षक शाळेत काम करतात.","id":136},{"subject":"Reasoning","topic":"Calendar","en":"If 1 January is a Monday in a non-leap year, what day is 1 February?","mr":"अधिवर्ष नसलेल्या वर्षात १ जानेवारी सोमवार असल्यास १ फेब्रुवारी कोणता वार?","options":["Thursday","Wednesday","Friday","Saturday"],"answer":0,"explanationEn":"January has 31 days; 31 mod 7 = 3, so Monday advances to Thursday.","explanationMr":"जानेवारीत ३१ दिवस; ३१ ला ७ ने भागल्यास बाकी ३. सोमवारानंतर गुरुवार.","id":137},{"subject":"Reasoning","topic":"Ranking","en":"Ravi is 12th from the left and 9th from the right in a row. How many people are in the row?","mr":"रवी रांगेत डावीकडून १२वा आणि उजवीकडून ९वा आहे. एकूण किती लोक?","options":["20","21","19","22"],"answer":0,"explanationEn":"Total = 12 + 9 − 1 = 20, counting Ravi once.","explanationMr":"एकूण = १२ + ९ − १ = २०; रवीची मोजणी एकदाच.","id":138},{"subject":"Reasoning","topic":"Word Formation","en":"How many meaningful English words can be formed using A, R and T once each?","mr":"A, R आणि T प्रत्येकी एकदाच वापरून किती अर्थपूर्ण इंग्रजी शब्द बनतात?","options":["3","2","4","6"],"answer":0,"explanationEn":"ART, RAT and TAR are three common meaningful words.","explanationMr":"ART, RAT आणि TAR असे तीन सामान्य अर्थपूर्ण शब्द आहेत.","id":139},{"subject":"Reasoning","topic":"Alphabet Series","en":"Find the missing letter: B, E, I, N, T, __.","mr":"गाळलेले अक्षर शोधा: B, E, I, N, T, __.","options":["A","Z","B","C"],"answer":0,"explanationEn":"Letter jumps are +3, +4, +5, +6; next +7 from T wraps to A.","explanationMr":"अक्षरांतील उड्या +३, +४, +५, +६; पुढील +७ मुळे T नंतर A येते.","id":140},{"subject":"Reasoning","topic":"Blood Relation","en":"A is the mother of B. C is the father of A. How is C related to B?","mr":"A ही B ची आई आहे. C हा A चा वडील आहे. C चे B शी नाते काय?","options":["Maternal grandfather","Paternal grandfather","Uncle","Brother"],"answer":0,"explanationEn":"C is the father of B's mother, so he is B's maternal grandfather.","explanationMr":"C हा B च्या आईचा वडील आहे; म्हणून तो आईकडील आजोबा.","id":141},{"subject":"Reasoning","topic":"Odd Number","en":"Select the number that does not belong: 8, 27, 64, 100, 125.","mr":"गटात न बसणारी संख्या निवडा: ८, २७, ६४, १००, १२५.","options":["100","8","27","125"],"answer":0,"explanationEn":"8, 27, 64 and 125 are perfect cubes; 100 is not.","explanationMr":"८, २७, ६४ आणि १२५ पूर्ण घन आहेत; १०० नाही.","id":142},{"subject":"Reasoning","topic":"Coding","en":"If MONDAY is coded as NPOEBZ by shifting each letter forward, how is FRIDAY coded?","mr":"MONDAY चे NPOEBZ असे कूट केल्यास FRIDAY चे कूट काय?","options":["GSJEBZ","GSJECZ","GRJEBZ","HSJEBZ"],"answer":0,"explanationEn":"Shift each letter one step forward: F-G, R-S, I-J, D-E, A-B, Y-Z.","explanationMr":"प्रत्येक अक्षर एक स्थान पुढे: F-G, R-S, I-J, D-E, A-B, Y-Z.","id":143},{"subject":"Reasoning","topic":"Ranking","en":"In a class of 40, Neha is 15th from the top. What is her rank from the bottom?","mr":"४० विद्यार्थ्यांच्या वर्गात नेहा वरून १५वी आहे. खालून तिचा क्रमांक कितवा?","options":["26th","25th","24th","27th"],"answer":0,"explanationEn":"Rank from bottom = 40 − 15 + 1 = 26.","explanationMr":"खालून क्रमांक = ४० − १५ + १ = २६.","id":144},{"subject":"Reasoning","topic":"Number Analogy","en":"Select the number pair that follows the same rule as 7:49.","mr":"७:४९ या जोडीप्रमाणेच नियम असलेली जोडी निवडा.","options":["9:81","8:56","6:30","5:20"],"answer":0,"explanationEn":"49 = 7²; 81 = 9², so 9:81 follows the same square rule.","explanationMr":"४९ = ७²; ८१ = ९²; म्हणून ९:८१ ही जोडी योग्य.","id":145},{"subject":"Reasoning","topic":"Direction","en":"A man walks 4 km east, turns left and walks 3 km. In which direction is he from the starting point?","mr":"एक माणूस ४ किमी पूर्वेला चालतो, डावीकडे वळून ३ किमी चालतो. तो सुरुवातीच्या ठिकाणाच्या कोणत्या दिशेला आहे?","options":["North-East","South-East","North-West","South-West"],"answer":0,"explanationEn":"After moving east, a left turn is north; the final position is north-east of the start.","explanationMr":"पूर्वेकडे गेल्यावर डावे वळणे म्हणजे उत्तर; त्यामुळे अंतिम स्थान ईशान्येला आहे.","id":146},{"subject":"Reasoning","topic":"Syllogism","en":"All roses are flowers. Some flowers fade quickly. Which conclusion must be true?","mr":"सर्व गुलाब फुले आहेत. काही फुले लवकर कोमेजतात. कोणता निष्कर्ष निश्चितपणे खरा आहे?","options":["All roses are flowers","All flowers are roses","Some roses fade quickly","No rose fades quickly"],"answer":0,"explanationEn":"The first statement directly establishes that every rose is a flower; the other conclusions do not necessarily follow.","explanationMr":"पहिल्या विधानानुसार प्रत्येक गुलाब फूल आहे; इतर निष्कर्ष निश्चितपणे निघत नाहीत.","id":147},{"subject":"Reasoning","topic":"Alphabet Position","en":"What is the position of M in the English alphabet?","mr":"इंग्रजी वर्णमालेत M चे स्थान कितवे आहे?","options":["13","12","14","15"],"answer":0,"explanationEn":"M is the 13th letter of the English alphabet.","explanationMr":"M हे इंग्रजी वर्णमालेतील १३ वे अक्षर आहे.","id":148},{"subject":"Reasoning","topic":"Number Series","en":"Find the next number: 1, 4, 9, 16, 25, __.","mr":"पुढील संख्या शोधा: १, ४, ९, १६, २५, __.","options":["36","30","35","49"],"answer":0,"explanationEn":"These are squares 1² through 5²; the next is 6² = 36.","explanationMr":"या १² ते ५² वर्गसंख्या आहेत; पुढील ६² = ३६.","id":149},{"subject":"Reasoning","topic":"Seating Order","en":"A, B and C sit in a row. A is not at either end and C sits to the right of B. Who sits in the middle?","mr":"A, B आणि C एका रांगेत बसले आहेत. A टोकाला नाही आणि C हा B च्या उजवीकडे आहे. मधोमध कोण?","options":["A","B","C","Cannot be determined"],"answer":0,"explanationEn":"A must be in the middle; the only arrangement satisfying the conditions is B-A-C.","explanationMr":"A टोकाला नसल्याने तो मधोमध असतो; अट पूर्ण करणारी मांडणी B-A-C आहे.","id":150},{"subject":"Reasoning","topic":"Clock","en":"What is the smaller angle between the hands of a clock at 3:00?","mr":"घड्याळात ३ वाजता काट्यांमधील लहान कोन किती?","options":["90°","60°","75°","120°"],"answer":0,"explanationEn":"At 3:00 the minute hand is at 12 and the hour hand at 3, a right angle of 90°.","explanationMr":"३ वाजता मिनिट काटा १२ वर आणि तास काटा ३ वर; कोन ९०°.","id":151},{"subject":"Reasoning","topic":"Classification","en":"Which one is different: January, March, May, June?","mr":"वेगळा पर्याय निवडा: जानेवारी, मार्च, मे, जून.","options":["June","January","March","May"],"answer":0,"explanationEn":"January, March and May have 31 days; June has 30.","explanationMr":"जानेवारी, मार्च आणि मेमध्ये ३१ दिवस; जूनमध्ये ३० दिवस.","id":152},{"subject":"Reasoning","topic":"Mathematical Operations","en":"If + means × and × means −, what is 6 + 4 × 5?","mr":"जर + म्हणजे × आणि × म्हणजे − असेल, तर 6 + 4 × 5 किती?","options":["19","24","29","9"],"answer":0,"explanationEn":"Replace the symbols: 6 × 4 − 5 = 24 − 5 = 19.","explanationMr":"चिन्हे बदलल्यास ६ × ४ − ५ = २४ − ५ = १९.","id":153},{"subject":"Reasoning","topic":"Letter Series","en":"Find the next pair: AB, DE, GH, JK, __.","mr":"पुढील अक्षरजोडी शोधा: AB, DE, GH, JK, __.","options":["MN","LM","NO","OP"],"answer":0,"explanationEn":"The starting letters advance by three positions: A, D, G, J, M; each pair contains consecutive letters.","explanationMr":"पहिली अक्षरे तीन स्थानांनी पुढे जातात: A, D, G, J, M; प्रत्येक जोडीतील अक्षरे सलग आहेत.","id":154}];
const TEST_COUNT = 100, Q_PER_TEST = 100, DURATION = 60*60, NEGATIVE = 0.25;
// Recent-paper practice blueprint: fixed section order, subject-wise random draws.
const PAPER_BLUEPRINT = [["History",10],["Geography",8],["Economy",16],["Current Affairs",16],["Polity",15],["Science",15],["Maths",12],["Reasoning",8]];
let active = null, activePaper = [], timer = null, remaining = DURATION, answers = {}, marked = new Set(), current = 0, submitted = false;
const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function getHistory(){try{return JSON.parse(localStorage.getItem('mpscHistory')||'[]')}catch{return []}}
function saveHistory(h){localStorage.setItem('mpscHistory',JSON.stringify(h))}
function seededRandom(seed){
  let x = seed >>> 0;
  return function(){
    x += 0x6D2B79F5;
    let t = x;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function shufflePool(pool, random){
  const items = [...pool];
  for(let i=items.length-1;i>0;i--){
    const j=Math.floor(random()*(i+1));
    [items[i],items[j]]=[items[j],items[i]];
  }
  return items;
}
function getPaper(n){
  const random=seededRandom(0x4D505343+n*7919);
  const paper=[];
  for(const [subject,count] of PAPER_BLUEPRINT){
    const pool=BANK.filter(q=>q.subject===subject);
    if(pool.length<count) throw new Error("Insufficient questions for "+subject+": "+pool.length+" available, "+count+" required.");
    paper.push(...shufflePool(pool,random).slice(0,count));
  }
  if(paper.length!==Q_PER_TEST || new Set(paper.map(q=>q.id)).size!==Q_PER_TEST){
    throw new Error("Paper generation failed: expected 100 unique question IDs.");
  }
  return paper;
}
function renderHome(){
  clearInterval(timer); active=null;
  const h=getHistory(), done=new Set(h.map(x=>x.paper));
  $('#app').innerHTML=`<header><div class="brand">MPSC <b>GROUP C</b><small>PRELIMS • MOCK TEST SERIES 2026–27</small></div><span class="badge">मराठी + English</span></header>
  <section class="hero"><div><p class="eyebrow">PREPARE • PRACTISE • IMPROVE</p><h1>Your MPSC Group C<br><em>Online Test Portal</em></h1><p>Timed mock tests, instant scoring, explanations and performance tracking.</p><button class="primary" id="startFirst">Start a mock test →</button></div><div class="hero-stat"><strong>100</strong><span>Mock test slots</span><strong>${BANK.length}</strong><span>Question bank entries</span></div></section>
  <section class="stats"><div><b>${done.size}</b><span>Tests completed</span></div><div><b>${h.length?Math.round(h.reduce((a,x)=>a+x.score,0)/h.length*10)/10:0}</b><span>Average score</span></div><div><b>${h.length?Math.max(...h.map(x=>x.score)):0}</b><span>Best score</span></div><div><b>${h.length?Math.round(h.reduce((a,x)=>a+x.accuracy,0)/h.length):0}%</b><span>Average accuracy</span></div></section>
  <div class="section-title"><div><h2>Mock test library</h2><p>Fixed subject blocks · 100 questions · 60-minute timer.</p></div><span class="muted">${done.size}/100 completed</span></div>
  <div class="grid">${Array.from({length:TEST_COUNT},(_,i)=>{let n=i+1,level=n<=20?'Foundation':n<=40?'Moderate':n<=60?'Advanced':n<=80?'PYQ pattern':'Full simulation';return `<article class="test-card"><div class="card-top"><span class="pill">${level}</span><span class="check">${done.has(n)?'✓ Completed':'100 Questions'}</span></div><h3>Mock Test ${String(n).padStart(2,'0')}</h3><p>100 marks · 60 minutes · −0.25 negative marking</p><button class="outline" data-paper="${n}">${done.has(n)?'Retake test':'Start test'} →</button></article>`}).join('')}</div>
  <section class="history"><h2>Recent attempts</h2>${h.length?h.slice(-5).reverse().map(x=>`<div class="history-row"><span>Mock Test ${String(x.paper).padStart(2,'0')}</span><b>${x.score}/100</b><span>${x.correct} correct · ${x.wrong} wrong</span><span>${x.date}</span></div>`).join(''):'<p class="muted">Your completed tests will appear here. Results are saved on this device.</p>'}</section>
  <footer>Practice resource only • Not affiliated with MPSC • Verify the latest official syllabus and exam pattern.</footer>`;
  $('#startFirst').onclick=()=>startTest(1);
  document.querySelectorAll('[data-paper]').forEach(b=>b.onclick=()=>startTest(+b.dataset.paper));
}
function startTest(n){
  active=n; answers={};marked=new Set();current=0;submitted=false;remaining=DURATION;
  const paper=getPaper(n); activePaper=paper;
  $('#app').innerHTML=`<header><div class="brand">MPSC <b>GROUP C</b><small>MOCK TEST ${String(n).padStart(2,'0')}</small></div><div class="timer" id="timer">60:00</div><button class="link" id="exit">Exit test</button></header>
  <div class="exam-layout"><main class="question-panel"><div class="q-meta"><span id="qcount">Question 1 of 100</span><span class="pill" id="subject"></span></div><div class="progress"><i id="progress"></i></div><h2 id="q-en"></h2><h3 id="q-mr"></h3><div id="options" class="options"></div><div class="q-actions"><button class="soft" id="clear">Clear response</button><button class="mark" id="mark">☆ Mark for review</button><span class="spacer"></span><button class="soft" id="prev">← Previous</button><button class="primary" id="next">Save & Next →</button></div></main>
  <aside class="palette"><h3>Question palette</h3><div class="legend"><span class="answered"></span> Answered <span class="review"></span> Review</div><div class="numbers" id="numbers"></div><div class="palette-bottom"><p id="counts"></p><button class="submit" id="submit">Submit test</button></div></aside></div>`;
  $('#exit').onclick=()=>{if(confirm('Exit this test? Your current attempt will be lost.'))renderHome()};
  $('#prev').onclick=()=>{if(current>0){current--;renderQuestion()}};
  $('#next').onclick=()=>{if(current<99){current++;renderQuestion()}else{renderQuestion()}};
  $('#clear').onclick=()=>{delete answers[current];renderQuestion()};
  $('#mark').onclick=()=>{marked.has(current)?marked.delete(current):marked.add(current);renderQuestion()};
  $('#submit').onclick=()=>finishTest();
  renderQuestion(); timer=setInterval(()=>{remaining--;$('#timer').textContent=formatTime(remaining);if(remaining<=0)finishTest(true)},1000);
}
function formatTime(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function renderQuestion(){
 const q=activePaper[current];
 $('#qcount').textContent=`Question ${current+1} of 100`;$('#subject').textContent=q.subject;
 $('#q-en').textContent=q.en;$('#q-mr').textContent=q.mr;
 $('#progress').style.width=((current+1))+'%';
 $('#options').innerHTML=q.options.map((o,i)=>`<button class="option ${answers[current]===i?'selected':''}" data-opt="${i}"><span>${'ABCD'[i]}</span>${esc(o)}</button>`).join('');
 document.querySelectorAll('[data-opt]').forEach(b=>b.onclick=()=>{answers[current]=+b.dataset.opt;renderQuestion()});
 $('#mark').textContent=marked.has(current)?'★ Marked for review':'☆ Mark for review';
 $('#prev').disabled=current===0;$('#next').textContent=current===99?'Review answers':'Save & Next →';
 $('#numbers').innerHTML=Array.from({length:100},(_,i)=>`<button class="num ${answers[i]!==undefined?'done':''} ${marked.has(i)?'flag':''} ${i===current?'active':''}" data-go="${i}">${i+1}</button>`).join('');
 document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{current=+b.dataset.go;renderQuestion()});
 $('#counts').textContent=`Answered ${Object.keys(answers).length}/100 · Marked ${marked.size}`;
}
function finishTest(auto=false){
 if(submitted)return;
 if(!auto&&!confirm('Submit your test now?'))return;
 submitted=true;clearInterval(timer);
 const paper=activePaper;let correct=0,wrong=0,blank=0;
 paper.forEach((q,i)=>{if(answers[i]===undefined)blank++;else if(answers[i]===q.answer)correct++;else wrong++});
 const score=correct-wrong*NEGATIVE,attempted=correct+wrong,accuracy=attempted?Math.round(correct/attempted*100):0;
 const result={paper:active,correct,wrong,blank,score:Math.round(score*100)/100,accuracy,date:new Date().toLocaleString()};
 const h=getHistory();h.push(result);saveHistory(h);
 renderResult(result,paper,auto);
}
function renderResult(r,paper,auto){
 $('#app').innerHTML=`<header><div class="brand">MPSC <b>GROUP C</b><small>TEST RESULT</small></div><button class="link" id="home">Dashboard</button></header>
 <section class="result-hero"><p class="eyebrow">${auto?'TIME EXPIRED':'TEST SUBMITTED'}</p><h1>Your result</h1><div class="score">${r.score}<small>/ 100</small></div><p>Mock Test ${String(r.paper).padStart(2,'0')} · ${r.date}</p></section>
 <section class="stats result-stats"><div><b>${r.correct}</b><span>Correct</span></div><div><b>${r.wrong}</b><span>Incorrect</span></div><div><b>${r.blank}</b><span>Unattempted</span></div><div><b>${r.accuracy}%</b><span>Accuracy</span></div></section>
 <div class="review-head"><h2>Answer review & explanations</h2><button class="primary" id="again">Retake test</button></div><div class="review-list">${paper.map((q,i)=>`<article class="review-item"><div class="review-q"><b>Q${i+1}. ${esc(q.en)}</b><p>${esc(q.mr)}</p></div><p class="${answers[i]===q.answer?'good':'bad'}">Your answer: ${answers[i]===undefined?'Not attempted':esc(q.options[answers[i]])}</p><p class="good">Correct answer: ${esc(q.options[q.answer])}</p><p>${esc(q.explanationEn)}</p><p class="muted">${esc(q.explanationMr)}</p></article>`).join('')}</div>`;
 $('#home').onclick=renderHome;$('#again').onclick=()=>startTest(r.paper);
}
renderHome();
